    nextGeneration(state);
  state.sid = sid;
  if (state.sidecar?.sid === sid)
    return;
  if (state.run === undefined) {
    const startedAt = await $.clock.now();
    state.run = { id: sidecarRunId(startedAt, Math.random()), startedAt };
  }
